describe('WCAG 2.1 AA Color Contrast Compliance', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.injectAxe();
  });

  it('should meet WCAG 2.1 AA color contrast standards for all text elements', () => {
    cy.checkA11y(null, {
      rules: {
        'color-contrast': { enabled: true }
      }
    }, (violations) => {
      expect(violations).to.have.lengthOf(0);
    });
  });

  it('should verify contrast ratio of 4.5:1 for normal text and 3:1 for large text', () => {
    cy.get('body').then(($body) => {
      const textElements = $body.find('p, span, a, label, h1, h2, h3, h4, h5, h6, button');

      textElements.each((index, element) => {
        cy.wrap(element).then(($el) => {
          const computedStyle = window.getComputedStyle($el[0]);
          const color = computedStyle.color;
          const backgroundColor = computedStyle.backgroundColor;
          const fontSize = parseFloat(computedStyle.fontSize);
          const fontWeight = computedStyle.fontWeight;

          // Calculate contrast ratio using WCAG formula
          const rgb1 = parseRgb(color);
          const rgb2 = parseRgb(backgroundColor);

          if (rgb1 && rgb2) {
            const contrastRatio = calculateContrastRatio(rgb1, rgb2);
            const isLargeText = fontSize >= 18 || (fontSize >= 14 && parseInt(fontWeight) >= 700);
            const minRatio = isLargeText ? 3 : 4.5;

            expect(contrastRatio).to.be.at.least(minRatio);
          }
        });
      });
    });
  });

  it('should verify contrast for interactive elements like buttons and links', () => {
    cy.get('button, a[href], input[type="button"]').each(($element) => {
      cy.wrap($element).should('be.visible').then(($el) => {
        const computedStyle = window.getComputedStyle($el[0]);
        const color = computedStyle.color;
        const backgroundColor = computedStyle.backgroundColor;

        const rgb1 = parseRgb(color);
        const rgb2 = parseRgb(backgroundColor);

        if (rgb1 && rgb2) {
          const contrastRatio = calculateContrastRatio(rgb1, rgb2);
          expect(contrastRatio).to.be.at.least(4.5);
        }
      });
    });
  });

  it('should handle edge case of transparent or inherited colors', () => {
    cy.get('*').each(($element) => {
      const computedStyle = window.getComputedStyle($element[0]);
      const color = computedStyle.color;
      const backgroundColor = computedStyle.backgroundColor;

      // Skip elements with transparent backgrounds
      if (backgroundColor === 'rgba(0, 0, 0, 0)' || backgroundColor === 'transparent') {
        cy.wrap($element).should('exist');
      } else {
        const rgb1 = parseRgb(color);
        const rgb2 = parseRgb(backgroundColor);

        if (rgb1 && rgb2 && isValidColor(rgb1) && isValidColor(rgb2)) {
          const contrastRatio = calculateContrastRatio(rgb1, rgb2);
          expect(contrastRatio).to.be.at.least(3);
        }
      }
    });
  });

  it('should verify focus indicators have sufficient contrast', () => {
    cy.get('button, a, input').each(($element) => {
      cy.wrap($element).focus().then(($el) => {
        const focusStyle = window.getComputedStyle($el[0], ':focus');
        const outlineColor = focusStyle.outlineColor;
        const backgroundColor = focusStyle.backgroundColor;

        const rgb1 = parseRgb(outlineColor);
        const rgb2 = parseRgb(backgroundColor);

        if (rgb1 && rgb2) {
          const contrastRatio = calculateContrastRatio(rgb1, rgb2);
          expect(contrastRatio).to.be.at.least(3);
        }
      });
    });
  });
});

function parseRgb(rgbString) {
  const match = rgbString.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
  if (match) {
    return {
      r: parseInt(match[1]),
      g: parseInt(match[2]),
      b: parseInt(match[3])
    };
  }
  return null;
}

function isValidColor(rgb) {
  return rgb && typeof rgb.r === 'number' && typeof rgb.g === 'number' && typeof rgb.b === 'number';
}

function getLuminance(rgb) {
  const [r, g, b] = [rgb.r, rgb.g, rgb.b].map(val => {
    val = val / 255;
    return val <= 0.03928 ? val / 12.92 : Math.pow((val + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

function calculateContrastRatio(rgb1, rgb2) {
  const lum1 = getLuminance(rgb1);
  const lum2 = getLuminance(rgb2);
  const lighter = Math.max(lum1, lum2);
  const darker = Math.min(lum1, lum2);
  return (lighter + 0.05) / (darker + 0.05);
}
